from pathlib import Path
C=Path('/workspace/output/nightchamfer')
def append(n,s):
 p=C/'elements'/n/'element.css';p.write_text(p.read_text()+'\n'+s.replace('$',f'[data-el="nightchamfer-{n}"]')+'\n')
append('hierarchy','''$ {padding-top:0;align-items:flex-end;gap:var(--gap-sm)}$>.root{height:30%;max-width:180px;left:42%;width:16%;border-width:10px}$>.branch{height:58%;align-self:flex-end;gap:var(--gap-sm);justify-content:flex-start}$ .node{flex:none;padding:calc(var(--gap-sm)/2);font-size:var(--type-16)}$ .node .name{font-size:var(--type-16)}$ .leaf{flex:1;min-height:0;padding:calc(var(--gap-sm)/2);display:flex;align-items:center;justify-content:center;font-size:var(--type-14)}$ .leaf .name{font-size:var(--type-16)}@container(max-height:350px){$ .leaf .name,$ .node .name{font-size:var(--type-12)}$>.branch{gap:calc(var(--gap-sm)/2)}$>.root .name{font-size:var(--type-14)}}''')
append('headline','''@container(max-height:130px){$ h2,$.big h2{font-size:var(--type-24);line-height:var(--title-line)}$ .kick{display:none}$ .note{font-size:var(--type-12);line-height:var(--label-line)}}''')
append('metric','''@container(max-height:130px){$ .parts{gap:calc(var(--gap-sm)/3)}$ .parts .fig{font-size:var(--type-24)}$ .parts .name{font-size:var(--type-14)}$ .parts .note{font-size:var(--type-12);line-height:var(--label-line)}$.stats>.stat{padding:calc(var(--gap-sm)/2)}}''')
append('bullet','''$.bullets{display:grid;grid-auto-rows:minmax(0,1fr);gap:var(--gap-sm)}$.bullet,$>.bullet{min-height:0;gap:0;padding:0 0 var(--gap);align-content:center}$.bullet .fig,$>.bullet .fig{font-size:var(--type-24)}$.bullet .name,$>.bullet .name{font-size:var(--type-16)}$.bullet .note,$>.bullet .note{font-size:var(--type-12)}$.bullet::after,$>.bullet::after{max-width:100%}@container(max-height:320px){$>.bullet .fig{font-size:var(--type-20)}$>.bullet .name{font-size:var(--type-14)}$>.bullet{padding-bottom:var(--gap-sm)}$>.bullet::before{height:8px}$>.bullet::after{height:4px;bottom:2px}$>.bullet .note::after{height:12px}}''')
append('waffle','''$.figures{display:flex;align-items:center;justify-content:center;padding:0;gap:var(--gap-sm)}$.figures>.units{height:auto;max-height:100%;flex:1;min-width:0;grid-template-columns:repeat(10,minmax(0,1fr));gap:calc(var(--gap-sm)/3)}$.figures>.fig{align-self:center;font-size:var(--type-24);white-space:nowrap}$.figures>.name{align-self:center;font-size:var(--type-14);line-height:var(--label-line);width:30%}$.figures small{display:block;font-size:var(--type-12)}@container(max-height:90px){$.figures>.fig{font-size:var(--type-18)}$.figures>.name{font-size:var(--type-12)}$.figures small{font-size:var(--type-10)}}''')
append('treemap','''$ .tile{flex-direction:row;gap:calc(var(--gap-sm)/2);padding:calc(var(--gap-sm)/2)}$ .tile .name{font-size:var(--type-16);overflow-wrap:anywhere}$ .tile .fig{font-size:var(--type-22);white-space:nowrap}@container(max-height:350px){$ .tile .name{font-size:var(--type-14)}$ .tile .fig{font-size:var(--type-18)}}''')
append('card','''$ .parts{display:grid;grid-template-columns:1fr;grid-auto-rows:auto;align-content:center;justify-items:center;gap:var(--gap-sm)}$ .parts>.name{min-height:calc(2em * var(--name-line));display:flex;align-items:flex-start;justify-content:center;align-self:start}$ .parts>.note{min-height:calc(3em * var(--body-line));align-self:start}$ .parts>.fig{align-self:end}$ .parts>.mark{align-self:center}@container(max-height:230px){$ .parts>.name{min-height:0}$ .parts>.note{min-height:0}$ .parts{gap:calc(var(--gap-sm)/3)}}''')
# Normalise non-canonical fixture placement while preserving canonical fixture bytes.
required={'card','callout','chart-area','chart-bar','chart-donut','chart-line'}
import re
for d in (C/'elements').iterdir():
 if d.name in required:continue
 for p in (d/'fixtures').glob('*.html'):
  s=p.read_text();s=re.sub(r'grid-column:\s*\d+\s*/\s*span\s*\d+;\s*grid-row:\s*\d+\s*/\s*span\s*\d+','grid-column:1 / span 12; grid-row:1 / span 6',s,count=1)
  p.write_text(s)
